version.transform:
/*
 * WORKCENTER SPARK WIN/LOSS CHART - MODE PERIODS
 * Each bar represents a mode change period (occurAt to endAt)
 * W = Running mode, L = Not running mode
 * INPUT: { "wcId": "wc-xxx", "tz": "America/Detroit" }
 */

(
  /* Configuration */
  $tz := $.tz ? $.tz : $momentTzGuess();
  $wcId := $.wcId ? $.wcId 
    : $metadata.urlParameters.id ? $metadata.urlParameters.id 
    : $metadata.querystring.workcenterId ? $metadata.querystring.workcenterId
    : $metadata.querystring.wcId ? $metadata.querystring.wcId
    : "wc-vmc-c1";
  
  /* Rolling 24 hour window */
  $now := $moment().tz($tz);
  $startMoment := $moment($now).subtract(24, 'hours');
  $endMoment := $now;
  $endTimeStr := $endMoment.format();
  
  /* Query workcenter history */
  $statement := 'query($wcId: String!, $startTime: DateTime!, $endTime: DateTime!) {
    workcenterHistory(
      where: {
        _and: [
          { workcenterId: { _eq: $wcId } },
          {
            _or: [
              { endAt: { _isNull: true } },
              { 
                _and: [
                  { occurAt: { _gte: $startTime } },
                  { occurAt: { _lte: $endTime } }
                ]
              },
              {
                _and: [
                  { endAt: { _gte: $startTime } },
                  { endAt: { _lte: $endTime } }
                ]
              }
            ]
          }
        ]
      },
      orderBy: [{ field: occurAt, direction: asc }]
    ) {
      edges {
        node {
          id
          occurAt
          endAt
          mode { id, name, code }
          state { id, name, code }
          workcenter { code, name }
        }
      }
    }
  }';
  
  $result := $query({
    "statement": $statement,
    "variables": {
      "wcId": $wcId,
      "startTime": $startMoment.format(),
      "endTime": $endMoment.format()
    }
  });
  
  $records := $result.workcenterHistory.edges.node ? $result.workcenterHistory.edges.node : [];
  $wcCode := $count($records) > 0 and $records[0].workcenter.code ? $records[0].workcenter.code : $wcId;
  $wcName := $count($records) > 0 and $records[0].workcenter.name ? $records[0].workcenter.name : $wcCode;
  
  /* Sort by occurAt */
  $sorted := $sort($records, function($a, $b) { $toMillis($a.occurAt) - $toMillis($b.occurAt) });
  
  /* Define "Running" modes - adjust these to match your data */
  $runningModes := ["Running", "Production", "Producing", "RUN"];
  
  /* Process each mode change period into W/L data point */
  $periodData := $map($sorted, function($r) {(
    $modeName := $r.mode.name ? $r.mode.name : "Unknown";
    $modeCode := $r.mode.code ? $r.mode.code : "";
    $isRunning := $modeName in $runningModes or $modeCode in $runningModes;
    
    /* Use endAt or current time if null */
    $periodStart := $r.occurAt;
    $periodEnd := $r.endAt ? $r.endAt : $endTimeStr;
    
    /* Calculate duration */
    $startMs := $toMillis($periodStart);
    $endMs := $toMillis($periodEnd);
    $durationMs := $endMs - $startMs;
    $durationMins := $floor($durationMs / 60000);
    $durationHrs := $floor($durationMins / 60);
    $remainMins := $durationMins % 60;
    
    /* Format duration string */
    $durationStr := $durationHrs > 0 
      ? $string($durationHrs) & "h " & $string($remainMins) & "m"
      : $string($durationMins) & "m";
    
    /* Format times for tooltip */
    $startTimeStr := $moment($periodStart).tz($tz).format('h:mm A');
    $endTimeStr := $r.endAt ? $moment($periodEnd).tz($tz).format('h:mm A') : "Now";
    
    {
      "value": $isRunning ? "W" : "L",
      "tooltext": $modeName & "{br}" & $startTimeStr & " - " & $endTimeStr & "{br}Duration: " & $durationStr
    }
  )});
  
  /* Handle empty data */
  $dataPoints := $count($periodData) > 0 ? $periodData : [{"value": "D", "tooltext": "No Data"}];
  
  /* Count wins/losses */
  $wins := $count($dataPoints[value = "W"]);
  $losses := $count($dataPoints[value = "L"]);
  $total := $count($dataPoints);
  
  /* Calculate uptime percentage */
  $uptimePct := $total > 0 ? $round(($wins / $total) * 100, 0) : 0;
  
  {
    "chart": {
      "caption": $wcName & " - Mode History",
      "subcaption": "Last 24 Hours (" & $string($wins) & "W / " & $string($losses) & "L - " & $string($uptimePct) & "% Uptime)",
      "theme": "fusion",
      
      /* Win/Loss/Draw colors */
      "wincolor": "70AD47",
      "losscolor": "ED7D31",
      "drawcolor": "A5A5A5",
      
      /* Hover colors */
      "winhovcolor": "5B9433",
      "losshovcolor": "D66A1F",
      "drawhovcolor": "8C8C8C",
      
      /* Score threshold */
      "scoreless": "0",
      
      /* Margins */
      "charttopmargin": "10",
      "chartbottommargin": "10",
      "chartleftmargin": "10",
      "chartrightmargin": "10",
      
      /* Border */
      "showborder": "0",
      
      /* Background */
      "bgcolor": "FFFFFF",
      "bgalpha": "100",
      
      /* Canvas */
      "canvasbgcolor": "FFFFFF",
      "canvasbgalpha": "100",
      "showcanvasborder": "0",
      
      /* Period line styling */
      "periodcolor": "5B9BD5",
      "periodalpha": "50",
      "periodlength": "1",
      
      /* Tooltip */
      "showtooltip": "1",
      "tooltipbgcolor": "FFFFFF",
      "tooltipbordercolor": "CCCCCC",
      "tooltippadding": "8",
      "tooltipborderradius": "4",
      
      /* Fonts */
      "basefont": "Inter, -apple-system, BlinkMacSystemFont, sans-serif",
      "basefontsize": "11",
      "basefontcolor": "333333",
      
      /* Value display */
      "showvalue": "0",
      "showopenvalue": "0",
      "showclosevalue": "0",
      "showhighvalue": "0",
      "showlowvalue": "0",
      "showopenanchor": "0",
      "showcloseanchor": "0",
      "showhighanchor": "0",
      "showlowanchor": "0"
    },
    "dataset": [{
      "data": $dataPoints
    }]
  })
